	@Test
	void readCursorReusesItsSegmentAndExpandsTheValidatedRange() {
		LmdbAdjacencyArena arena = new LmdbAdjacencyArena(TEST_REGION_BYTES);
		long firstRef = arena.allocateRef(64, 8);
		long secondRef = arena.allocateRef(16, 8);
		LmdbAdjacencyArena.ReadCursor cursor = new LmdbAdjacencyArena.ReadCursor();

		arena.resolve(firstRef, 8, cursor);
		MemorySegment firstSegment = cursor.segment();
		long firstOffset = cursor.baseOffset();
		firstSegment.set(LmdbAdjacencyArena.U64_LE, firstOffset, 0x0102030405060708L);

		assertThat(cursor.covers(firstRef, 8)).isTrue();
		assertThat(cursor.covers(firstRef, 64)).isFalse();
		arena.expand(firstRef, 64, cursor);
		assertThat(cursor.segment()).isSameAs(firstSegment);
		assertThat(cursor.baseOffset()).isEqualTo(firstOffset);
		assertThat(cursor.validatedBytes()).isEqualTo(64);
		assertThat(cursor.segment().get(LmdbAdjacencyArena.U64_LE, cursor.baseOffset()))
				.isEqualTo(0x0102030405060708L);

		arena.resolve(secondRef, 16, cursor);
		assertThat(cursor.covers(secondRef, 16)).isTrue();
		assertThat(cursor.covers(firstRef, 8)).isFalse();
		assertThatIllegalArgumentException().isThrownBy(() -> arena.expand(firstRef, 8, cursor));

		arena.close();
		assertThatThrownBy(() -> arena.resolve(secondRef, 8, cursor)).isInstanceOf(IllegalStateException.class);
	}

